-- 三张用户信息表 + 一张用户聊天记录表
-- 手机号 phone / phone_snapshot 是跨表串联核心索引
-- 可直接在 Supabase SQL Editor 执行，可重复运行

create extension if not exists pgcrypto;

create table if not exists public."user_info" (
  "id" bigint generated by default as identity primary key,
  "user_no" varchar(64),
  "org_id" bigint,
  "openid" varchar(128),
  "unionid" varchar(128),
  "mini_openid" varchar(128),
  "mp_openid" varchar(128),
  "group_openid" varchar(128),
  "token" varchar(256),
  "nick_name" varchar(128) not null,
  "avatar_url" varchar(512),
  "gender" integer not null,
  "phone" varchar(32) not null check (btrim("phone") <> ''),
  "phone_mask" varchar(32),
  "phone_verified" boolean,
  "phone_source" varchar(64),
  "phone_authorized" boolean,
  "real_name" varchar(64),
  "is_authorized" boolean,
  "birthday" date,
  "age" integer,
  "location" varchar(100),
  "source_type" varchar(32) not null,
  "source_detail" varchar(255),
  "tags" jsonb,
  "profile" jsonb,
  "status" smallint default 1 not null,
  "remark" varchar(1000),
  "privacy_consent" smallint default 0 not null,
  "consent_time" timestamptz,
  "first_seen_at" timestamptz,
  "last_active_at" timestamptz,
  "merge_to_user_id" bigint,
  "merge_status" varchar(32),
  "wechat_profile_updated_at" timestamptz,
  "created_at" timestamptz default now() not null,
  "updated_at" timestamptz default now() not null,
