  "wechat_group_nickname" varchar(128),
  "enroll_wechat_group_name" varchar(255),
  "enroll_wechat_group_id" varchar(128),
  "enroll_wechat_group_nickname" varchar(128),
  "first_source_group_id" varchar(128),
  "first_source_group_name" varchar(255),
