  "gene_created_at" timestamptz,
  "gene_bindings_raw" jsonb,
  "sample_binding_id" bigint,
  "sample_user_name" varchar(64),
  "sample_sex" varchar(10),
  "sample_phone" varchar(32),
  "sample_vcode_last" varchar(10),
  "sample_agree" boolean,
  "sample_detection_type" varchar(20),
  "sample_id" varchar(50),
  "sample_bind_status" varchar(20),
  "sample_created_at" timestamptz,
  "sample_bindings_raw" jsonb,
  "sms_last_id" bigint,
  "sms_last_phone" varchar(32),
