-- 小程序原始用户信息表：一个手机号一条原始记录
create table if not exists public.user_info_mini (
  id bigint generated by default as identity primary key,
  phone varchar(32) not null check (btrim(phone) <> ''),
  nick_name varchar(128),
  real_name varchar(64),
  avatar_url varchar(512),
  openid varchar(128),
  unionid varchar(128),
  mini_openid varchar(128),
  mp_openid varchar(128),
  gender integer default 0,
  birthday date,
  location varchar(100),
  source_detail varchar(255),
  status smallint not null default 1,
  calibrated_user_id bigint references public.user_info(id) on delete set null,
  raw_data jsonb not null default '{}'::jsonb,
  last_synced_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists user_info_mini_phone_uk
  on public.user_info_mini (phone);
create index if not exists user_info_mini_openid_idx
  on public.user_info_mini (openid);
create index if not exists user_info_mini_unionid_idx
  on public.user_info_mini (unionid);
create index if not exists user_info_mini_calibrated_user_id_idx
  on public.user_info_mini (calibrated_user_id);

-- 智能体原始用户信息表：一个手机号一条原始记录
create table if not exists public.user_info_agent (
  id bigint generated by default as identity primary key,
  phone varchar(32) not null check (btrim(phone) <> ''),
  nick_name varchar(128),
  real_name varchar(64),
  avatar_url varchar(512),
  openid varchar(128),
  unionid varchar(128),
  group_openid varchar(128),
  gender integer default 0,
  birthday date,
  location varchar(100),
  source_detail varchar(255),
  status smallint not null default 1,
  calibrated_user_id bigint references public.user_info(id) on delete set null,
  raw_data jsonb not null default '{}'::jsonb,
  last_synced_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists user_info_agent_phone_uk
  on public.user_info_agent (phone);
create index if not exists user_info_agent_openid_idx
  on public.user_info_agent (openid);
create index if not exists user_info_agent_unionid_idx
  on public.user_info_agent (unionid);
create index if not exists user_info_agent_calibrated_user_id_idx
  on public.user_info_agent (calibrated_user_id);


create table if not exists public."chat_message" (
  "message_id" bigint generated by default as identity primary key,
  "wechat_msg_id" varchar(128),
  "session_id" varchar(128),
  "parent_message_id" bigint,
  "org_id" bigint,
  "group_id" varchar(128) not null,
  "group_name_snapshot" varchar(255),
  "group_nickname_snapshot" varchar(128),
  "sender_openid" varchar(128),
  "sender_openid_type" varchar(16),
  "sender_unionid" varchar(128),
  "sender_nickname_snapshot" varchar(128),
  "user_id" bigint,
  "phone_snapshot" varchar(32) not null check (btrim("phone_snapshot") <> ''),
  "customer_category_snapshot" varchar(20),
  "northland_member_id_snapshot" varchar(50),
  "box_type_snapshot" varchar(20),
  "detection_type_snapshot" varchar(20),
  "sample_id_snapshot" varchar(50),
  "enroll_status_snapshot" varchar(20),
  "business_domain_snapshot" varchar(64),
  "msg_type" varchar(32) not null,
  "content" text,
  "raw_content" jsonb,
  "media_url" varchar(1000),
  "send_time" timestamptz not null,
  "msg_direction" varchar(32) not null,
  "is_ai_reply" smallint default 0 not null,
  "robot_id" bigint,
  "related_knowledge_id" bigint,
  "hit_status" varchar(32),
  "is_sensitive" smallint default 0 not null,
  "desensitized_content" text,
  "memory_candidate" smallint default 0 not null,
  "memory_extract_status" varchar(32),
  "memory_summary" text,
  "memory_category" varchar(64),
  "memory_confidence" numeric(5,4),
  "memory_valid_from" timestamptz,
  "memory_valid_to" timestamptz,
  "is_deleted" smallint default 0 not null,
  "created_at" timestamptz default now() not null
);

