-- 聊天记录按手机号关联校准后的主用户；允许先落聊天、后补齐主用户
create index if not exists chat_message_phone_send_time_idx
  on public.chat_message (phone_snapshot, send_time desc);
create index if not exists chat_message_send_time_idx
  on public.chat_message (send_time desc);
create index if not exists chat_message_list_idx
  on public.chat_message (is_deleted, send_time desc);
create index if not exists chat_message_group_idx
  on public.chat_message (group_id, send_time desc);

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.chat_message'::regclass
      and conname = 'chat_message_user_id_fk'
  ) then
    alter table public.chat_message
      add constraint chat_message_user_id_fk
      foreign key (user_id) references public.user_info(id)
      on delete set null;
  end if;
end $$;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.chat_message'::regclass
      and conname = 'chat_message_parent_message_id_fk'
  ) then
    alter table public.chat_message
      add constraint chat_message_parent_message_id_fk
      foreign key (parent_message_id) references public.chat_message(message_id)
      on delete set null;
  end if;
end $$;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.user_info'::regclass
      and conname = 'user_info_merge_to_user_id_fk'
  ) then
    alter table public.user_info
      add constraint user_info_merge_to_user_id_fk
      foreign key (merge_to_user_id) references public.user_info(id)
      on delete set null;
  end if;
end $$;



create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists user_info_mini_set_updated_at on public.user_info_mini;
create trigger user_info_mini_set_updated_at
before update on public.user_info_mini
for each row execute function public.set_updated_at();

drop trigger if exists user_info_agent_set_updated_at on public.user_info_agent;
create trigger user_info_agent_set_updated_at
before update on public.user_info_agent
for each row execute function public.set_updated_at();

drop trigger if exists user_info_set_updated_at on public.user_info;
create trigger user_info_set_updated_at
before update on public.user_info
for each row execute function public.set_updated_at();



-- 仅后端 secret/service_role 可访问；浏览器端 publishable key 默认读不到业务数据
alter table public.user_info_mini enable row level security;
alter table public.user_info_agent enable row level security;
alter table public.user_info enable row level security;
alter table public.chat_message enable row level security;

grant usage on schema public to service_role;
